// def __init__(self, p: Ptr[A]) -> None:
//     self.p = p
//     self.c = Color.RED
//     self.x = 1
//     self.s = "aaa"
//     self.raw = b"r\x02"
inline Sib::Sib(A* p)
    : p(p),
      c(Color::RED),
      x(1),
      s("aaa"),
      raw(::tpy::bytes_literal_owned("r\x02", 2)) {}
struct J {
    using variant_type = ::tpy::Union<std::vector<J>, std::string>;
    variant_type value;

    J() = default;
    template<typename T>
        requires std::constructible_from<variant_type, T&&>
    J(T&& v) : value(std::forward<T>(v)) {}

    bool operator==(const J&) const = default;

    std::string __str__() const {
        return ::tpy::__str__(static_cast<const typename variant_type::base_variant&>(value));
    }
    std::string __repr__() const {
        return ::tpy::__repr__(static_cast<const typename variant_type::base_variant&>(value));
    }

    friend std::ostream& operator<<(std::ostream& os, const J& v) {
        return os << v.__str__();
    }
};

