//     return str(v)
template<::tpystd::tpy::Stringable T_v>
std::string text_after_elem(const T_v& v, std::vector<int32_t>& xs) {
    ::tpy::__setitem__(xs, 0, 9);
    return std::string(::tpy::__str__(v));
}
// def opt_text(v: Stringable, o: A | None) -> str:
//     return str(v) + "/" + str(o)
template<::tpystd::tpy::Stringable T_v>
std::string opt_text(const T_v& v, const A* o) {
    return (::tpy::str_concat((::tpy::str_concat(std::string(::tpy::__str__(v)), "/")), std::string(::tpy::__str__(o))));
}
// # The compiler's winner is declared first (the CPython dispatch stub runs the
